ROOT = pathlib.Path('/Users/guillaumeloulier/PhpstormProjects/oss/elephc/.claude/worktrees/streams-csv-signature')


def cut_test(path, fn_name):
    """Removes one `#[test]` function together with the doc block above it."""
    p = ROOT / path
    t = p.read_text()
    at = t.index(f'fn {fn_name}(')
    start = t.rindex('\n#[test]\n', 0, at) + 1
    while True:
        prev = t.rindex('\n', 0, start - 1) + 1
        if not t[prev:].startswith('///'):
            break
        start = prev
    end = t.index('\n}\n', at) + len('\n}\n')
    if t[end:end + 1] == '\n':
        end
